use crate::ciphers::fnv1a::cipher::fnv1a_digest;
use crate::ciphers::fnv1a::keys::fnv1a_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one digest pass over `input_len` generated bytes.
pub fn fnv1a_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let seed = fnv1a_default_key();
    let watch = Stopwatch::start();
    let out = fnv1a_digest(&data, seed);
    std::hint::black_box(out);
    watch.elapsed_ns()
}
